function engagementComparisonBody(p){
  if(p.downloadName!=='Enterprise AI engagement model decision map')return '';
  const zh=p.lang.startsWith('zh');const cn=p.lang==='zh-CN';const key=cn?'cn':(zh?'zh':'en');const prefix=cn?'/zh-cn':(zh?'/zh-hk':'/en');
  const copy={
    en:{heading:'Compare the three engagement models',intro:'Choose by the uncertainty that must be removed and the evidence the engagement must produce—not by the most impressive label.',dimension:'Decision test',advisory:'AI advisory',custom:'Custom development',fde:'FDE',rows:[['Primary uncertainty','What should we do, and should we invest?','How should we build the defined system?','What intervention will work in the real operating environment?'],['Choose when','Opportunity, feasibility, governance, or sequence is unclear.','Users, workflow, interfaces, constraints, and tests can be specified.','The valuable problem is known, but the solution boundary must be learned in the field.'],['Accountable output','A signed decision with evidence, owner, and next gate.','A tested system against agreed scope and acceptance criteria.','A measurable operating outcome and a production-capable system.'],['Acceptance evidence','Recommendation, rejected options, assumptions, and next-stage gate.','Traceable functional, quality, security, and operational test results.','Baseline-to-outcome evidence, operator adoption, failure handling, and readiness gates.'],['Change mode when','Scope stabilises → custom development; field discovery is required → FDE.','Field evidence invalidates the specification → FDE; investment changes → advisory.','Uncertainty falls and ownership is clear → stable product delivery or managed operations.']]},
    zh:{heading:'比較三種參與模式',intro:'按需要消除的不確定性及必須產生的證據選擇，而不是按最吸引的服務名稱選擇。',dimension:'決策測試',advisory:'AI 顧問',custom:'定制開發',fde:'FDE',rows:[['主要不確定性','應該做甚麼，以及是否值得投入？','如何建設已定義的系統？','哪種干預在真實營運環境中有效？'],['適用條件','機會、可行性、治理或推進順序仍未清楚。','用戶、流程、接口、限制及測試可以定義。','高價值問題已知，但方案邊界必須在現場學習。'],['責任成果','有證據、負責人及下一關口的簽署決策。','按約定範圍及驗收標準測試的系統。','可量度的營運成果及可投入生產的系統。'],['驗收證據','建議、排除選項、假設及下一階段關口。','可追溯的功能、質量、安全及營運測試結果。','基線至成果證據、操作人員採用、失敗處理及就緒關口。'],['何時轉換','範圍穩定 → 定制開發；需要現場發現 → FDE。','現場證據推翻規格 → FDE；投資決策改變 → 顧問。','不確定性下降且責任清楚 → 穩定產品交付或持續營運。']]},
    cn:{heading:'比较三种合作模式',intro:'根据需要消除的不确定性以及项目必须产出的证据选择，而不是根据最吸引人的服务名称选择。',dimension:'决策测试',advisory:'AI 咨询',custom:'定制开发',fde:'FDE',rows:[['主要不确定性','应该做什么，以及是否值得投入？','如何建设已经定义的系统？','哪种干预在真实运营环境中有效？'],['适用条件','机会、可行性、治理或推进顺序仍不清楚。','用户、流程、接口、限制和测试可以定义。','高价值问题已经明确，但方案边界必须在现场学习。'],['责任成果','有证据、负责人和下一关口的签署决策。','按照约定范围和验收标准测试的系统。','可衡量的运营结果和可投入生产的系统。'],['验收证据','建议、排除选项、假设和下一阶段关口。','可追溯的功能、质量、安全和运营测试结果。','基线到结果证据、操作人员采用、失败处理和就绪关口。'],['何时转换','范围稳定 → 定制开发；需要现场发现 → FDE。','现场证据推翻规格 → FDE；投资决策改变 → 咨询。','不确定性下降且责任清楚 → 稳定产品交付或持续运营。']]},
  }[key];
  const servicePaths=zh?[`${prefix}/ai-consulting/`,`${prefix}/custom-ai-development/`,`${prefix}/forward-deployed-engineering/`]:['/en/ai-consulting-hong-kong/','/en/custom-ai-development-hong-kong/','/en/forward-deployed-engineering/'];
  return `<section class="engagement-comparison"><div class="wrap"><h2>${copy.heading}</h2><p class="intro">${copy.intro}</p><div class="comparison-scroll" tabindex="0" role="region" aria-label="${copy.heading}"><table><thead><tr><th scope="col">${copy.dimension}</th><th scope="col"><a href="${servicePaths[0]}">${copy.advisory}</a></th><th scope="col"><a href="${servicePaths[1]}">${copy.custom}</a></th><th scope="col"><a href="${servicePaths[2]}">${copy.fde}</a></th></tr></thead><tbody>${copy.rows.map(row=>`<tr><th scope="row">${row[0]}</th>${row.slice(1).map(value=>`<td>${value}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div></section>`;
}
